def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame logic: Defect in last few rounds to maximize payoff against cooperators
    if n >= 95:
        return 'D'

    my_last, opp_last = history[-1]

    # Calculate cooperation rates
    opp_c = sum(1 for _, o in history if o == 'C')
    my_c = sum(1 for m, _ in history if m == 'C')

    opp_rate = opp_c / n
    my_rate = my_c / n

    # Strategy Selection based on opponent behavior

    # 1. If opponent is highly defective, mirror or defect to minimize loss
    if opp_rate < 0.3:
        if opp_last == 'D':
            return 'D'
        # Occasional cooperation to test for mistakes/forgiveness
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # 2. If opponent is highly cooperative, exploit occasionally but maintain flow
    elif opp_rate > 0.7:
        if opp_last == 'C':
            # Exploit with low probability to avoid breaking mutual cooperation too often
            if rng.random() < 0.05:
                return 'D'
            return 'C'
        else:
            # Opponent defected despite high coop rate -> likely noise/mistake
            # Forgive (Cooperate) to restore CC state quickly
            return 'C'

    # 3. Mixed strategies (Tit-for-Tat style with forgiveness)
    else:
        if opp_last == 'C':
            # If we just defected and they forgave, cooperate to stabilize
            if my_last == 'D':
                return 'C'
            # Standard TFT response
            return 'C'
        else:
            # Opponent defected
            # Check recent pattern: if they have been consistently uncooperative recently, punish
            recent_opp_defects = sum(1 for _, o in history[-5:] if o == 'D')

            if recent_opp_defects >= 4:
                return 'D'

            # If it was a one-off defection or we were also defecting, consider forgiveness
            if my_last == 'D':
                # Mutual defection streak: try to break out by cooperating if they seem capable of C
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
            else:
                # We cooperated, they defected -> Retaliate once (TFT)
                # But add slight forgiveness if overall rate is decent
                if opp_rate > 0.6 and rng.random() < 0.2:
                    return 'C'
                return 'D'
